// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle, bricks } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks
  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      // Resolve collision: find the axis of least penetration
      const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

      if (overlapX < overlapY) {
        ball.vx = -ball.vx;
        ball.x += (ball.x + ball.r - brick.x < brick.x + brick.w - (ball.x - ball.r)) 
          ? -(ball.x + ball.r - brick.x) : (brick.x + brick.w - (ball.x - ball.r));
      } else {
        ball.vy = -ball.vy;
        ball.y += (ball.y + ball.r - brick.y < brick.y + brick.h - (ball.y - ball.r)) 
          ? -(ball.y + ball.r - brick.y) : (brick.y + brick.h - (ball.y - ball.r));
      }

      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
