import { createState, step, WIDTH, HEIGHT } from '../game/neon.js';
import assert from 'node:assert';
import test from 'node:test';

test('D1 - Ball should bounce off a brick top face', () => {
  const state = createState(1);
  const brick = state.bricks[0]; 
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; // overlap top
  state.ball.vy = 100; // DOWN
  state.ball.vx = 0;

  step(state, 0.01);

  assert.ok(state.ball.vy < 0, `Ball should bounce UP, but vy is ${state.ball.vy}`);
});

test('D2 - Ball should not tunnel through bricks at high speed', () => {
  const state = createState(10); // Level 10: speed = 1070
  const brick = state.bricks[0];

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1; 
  state.ball.vy = 1070; // DOWN
  state.ball.vx = 0;

  step(state, 0.05);

  assert.strictEqual(brick.alive, false, 'Ball should have hit the first brick (Row 0)');
});

test('D3 - Ball should not double-bounce at seams', () => {
  const state = createState(1);
  const b1 = state.bricks[0]; 
  const b2 = state.bricks[1];
  state.ball.y = b1.y + b1.h / 2;
  state.ball.x = b1.x + b1.w + 4; // Center of gap
  state.ball.vx = 100; // RIGHT
  state.ball.vy = 0;

  step(state, 0.01);

  assert.ok(state.ball.vx < 0, `Ball should have bounced LEFT, but vx is ${state.ball.vx}`);
});
